export const isValidParentDomain = (value: string): boolean => {
  const normalized = normalizeHost(value);
  const labels = normalized.split('.');
  return (
    labels.length >= 2 &&
    labels.every(
      (label) =>
        label.length > 0 && !label.startsWith(PUNYCODE_PREFIX) && HOST_LABEL_REGEX.test(label)
    )
  );
};

